import { useState, useMemo, useCallback } from 'react';
import { JxCalendar, JxButton } from '@jinx-ui/react';

type QuickOption = {
  label: string;
  getDate: () => Date;
};

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

const quickOptions: QuickOption[] = [
  {
    label: 'Сегодня',
    getDate: () => startOfDay(new Date()),
  },
  {
    label: 'Вчера',
    getDate: () => {
      const d = startOfDay(new Date());
      d.setDate(d.getDate() - 1);
      return d;
    },
  },
  {
    label: 'Неделя назад',
    getDate: () => {
      const d = startOfDay(new Date());
      d.setDate(d.getDate() - 7);
      return d;
    },
  },
];

export interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
}

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
}: ReportDatePickerProps) {
  const [internalValue, setInternalValue] = useState<Date | null>(defaultValue);
  const isControlled = value !== undefined;
  const currentValue = isControlled ? value : internalValue;

  const handleChange = useCallback(
    (next: Date | null) => {
      if (!isControlled) {
        setInternalValue(next);
      }
      onChange?.(next);
    },
    [isControlled, onChange]
  );

  const quickDates = useMemo(
    () => quickOptions.map((option) => ({ label: option.label, date: option.getDate() })),
    []
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        fontFamily: 'var(--jx-font-family-base)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
      >
        {quickDates.map(({ label, date }) => {
          const active = isSameDay(currentValue, date);
          return (
            <JxButton
              key={label}
              type="button"
              size="sm"
              variant={active ? 'primary' : 'outline'}
              aria-pressed={active}
              onClick={() => handleChange(date)}
            >
              {label}
            </JxButton>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={currentValue} onValueChange={handleChange} />
    </div>
  );
}

